package com.codingpit.muviss.feature.settings.domain

/**
 * One dependency's license grant, as shown on the Settings > About > Licenses screen. An artifact can carry a second
 * licence record (#615) when two shipped targets name different licences under the same coordinates, or when it is
 * dual-licensed; [secondLicenseName] is set only then.
 */
data class OssLicense(
    val groupId: String,
    val artifactId: String,
    val name: String,
    val licenseName: String,
    val licenseUrl: String?,
    val secondLicenseName: String? = null,
    val secondLicenseUrl: String? = null,
)

/**
 * Every direct + transitive OSS dependency this app ships, with its
